CREATE TYPE "Role" AS ENUM ('USER','ADMIN');
CREATE TYPE "UserStatus" AS ENUM ('ACTIVE','BLOCKED');
CREATE TYPE "Situation" AS ENUM ('LOST','FOUND','REUNITED','CLOSED');
CREATE TYPE "Sex" AS ENUM ('MALE','FEMALE','UNKNOWN');
CREATE TYPE "Size" AS ENUM ('SMALL','MEDIUM','LARGE','UNKNOWN');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"phone" TEXT,"whatsapp" TEXT,"city" TEXT,"state" TEXT,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'USER',"status" "UserStatus" NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE TABLE "Animal" ("id" TEXT PRIMARY KEY,"ownerId" TEXT NOT NULL,"name" TEXT,"species" TEXT NOT NULL,"breed" TEXT,"sex" "Sex" NOT NULL DEFAULT 'UNKNOWN',"size" "Size" NOT NULL DEFAULT 'UNKNOWN',"color" TEXT NOT NULL,"approximateAge" TEXT,"description" TEXT,"specialMarks" TEXT,"situation" "Situation" NOT NULL,"occurrenceDate" TIMESTAMP(3) NOT NULL,"street" TEXT,"neighborhood" TEXT NOT NULL,"city" TEXT NOT NULL,"state" TEXT NOT NULL,"referencePoint" TEXT,"latitude" DECIMAL(10,7),"longitude" DECIMAL(10,7),"contactName" TEXT NOT NULL,"contactPhone" TEXT,"contactWhatsapp" TEXT,"contactEmail" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Animal_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "Animal_situation_city_idx" ON "Animal"("situation","city"); CREATE INDEX "Animal_species_color_idx" ON "Animal"("species","color"); CREATE INDEX "Animal_ownerId_idx" ON "Animal"("ownerId"); CREATE INDEX "Animal_createdAt_idx" ON "Animal"("createdAt");
CREATE TABLE "AnimalImage" ("id" TEXT PRIMARY KEY,"animalId" TEXT NOT NULL,"url" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AnimalImage_animalId_fkey" FOREIGN KEY ("animalId") REFERENCES "Animal"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Sighting" ("id" TEXT PRIMARY KEY,"animalId" TEXT NOT NULL,"reporterId" TEXT NOT NULL,"sightingDate" TIMESTAMP(3) NOT NULL,"approximateTime" TEXT,"street" TEXT,"neighborhood" TEXT NOT NULL,"city" TEXT NOT NULL,"state" TEXT NOT NULL,"referencePoint" TEXT,"description" TEXT,"photoUrl" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Sighting_animalId_fkey" FOREIGN KEY ("animalId") REFERENCES "Animal"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "Sighting_reporterId_fkey" FOREIGN KEY ("reporterId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "Sighting_animalId_idx" ON "Sighting"("animalId"); CREATE INDEX "Sighting_reporterId_idx" ON "Sighting"("reporterId");
CREATE TABLE "RefreshToken" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"tokenHash" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"revokedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "RefreshToken_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE); CREATE UNIQUE INDEX "RefreshToken_tokenHash_key" ON "RefreshToken"("tokenHash"); CREATE INDEX "RefreshToken_userId_idx" ON "RefreshToken"("userId");
CREATE TABLE "PasswordResetToken" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"tokenHash" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"usedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PasswordResetToken_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE); CREATE UNIQUE INDEX "PasswordResetToken_tokenHash_key" ON "PasswordResetToken"("tokenHash"); CREATE INDEX "PasswordResetToken_userId_idx" ON "PasswordResetToken"("userId");
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY,"actorId" TEXT,"action" TEXT NOT NULL,"entityType" TEXT NOT NULL,"entityId" TEXT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AuditLog_actorId_fkey" FOREIGN KEY ("actorId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE); CREATE INDEX "AuditLog_actorId_idx" ON "AuditLog"("actorId"); CREATE INDEX "AuditLog_createdAt_idx" ON "AuditLog"("createdAt");
